fn bitwise_xor(a: Vec<u8>, b: Vec<u8>) -> Vec<u8> {
    // Create a new vector to store the result
    let mut result = Vec::with_capacity(a.len());
    
    // Iterate over the indices of the input vectors
    for i in 0..a.len() {
        // Perform bitwise XOR and push the result to the new vector
        result.push(a[i] ^ b[i]);
    }
    
    result
}